A JSON report is a structured document formatted in JSON (JavaScript Object Notation) designed to present data, metrics, or status information in a lightweight, machine-readable, and human-readable format. It is widely used in automated testing, CI/CD pipelines, analytics, system monitoring, and API communications.

Here is an example of a system health and automated test report:

```json
{
  "report_title": "Automated Test & Health Summary",
  "generated_at": "2025-05-18T10:30:00Z",
  "environment": "production",
  "status": "passed",
  "metrics": {
    "total_tests": 42,
    "passed": 40,
    "failed": 0,
    "skipped": 2,
    "execution_time_seconds": 12.45
  },
  "system_health": {
    "cpu_utilization_percent": 24.5,
    "memory_usage_mb": 1024,
    "disk_status": "healthy"
  },
  "details": [
    {
      "suite": "Authentication",
      "status": "passed",
      "duration_ms": 320
    },
    {
      "suite": "Payment Gateway",
      "status": "passed",
      "duration_ms": 1150
    },
    {
      "suite": "Legacy Export",
      "status": "skipped",
      "reason": "Feature flagged off"
    }
  ]
}
```
